SELECT COUNT(*) OVER() AS TOTNUM, A.* FROM( SELECT /*selectBuyerMdAmDepartmentAccountList*/ A.CODE ACCOUNT_CODE, A.TEXT2 ACCOUNT_NAME, B.CODE1 ACCOUNT_CODE1, DECODE(B.CODE2,NULL,'N','Y') CHECK_YN, NVL(B.FLAG,'Y') GUBUN -- FLAG = 'Y' 부서전용 , FLAG = 'N' 부서공통 FROM ICOMCOD2 A , ICOMCOD3 B WHERE 1=1
AND A.COMPANY_CODE = #{st_buyer}
AND A.COMPANY_CODE = #{SESSION_BUYER_CODE}
AND A.COMPANY_CODE = B.BUYER(+) AND A.TYPE = 'Z014' AND A.CODE = B.CODE2(+) AND B.TYPE(+) = 'DTOA' AND B.CODE1(+) = NVL(#{st_dept_code},'') ) A ORDER BY ACCOUNT_NAME

SELECT COUNT(*) OVER() AS TOTNUM, A.* FROM( SELECT /*getBuyerMdAmDepartmentAccountList_v2*/ A.CODE ACCOUNT_CODE, A.TEXT1 ACCOUNT_NAME, B.CODE1 ACCOUNT_CODE1, DECODE(B.CODE2,NULL,'N','Y') CHECK_YN, NVL(B.FLAG,'Y') GUBUN -- FLAG = 'Y' 부서전용 , FLAG = 'N' 부서공통 FROM ICOMCOD2 A , ICOMCOD3 B WHERE 1=1
AND A.COMPANY_CODE = #{st_buyer}
AND A.COMPANY_CODE = #{SESSION_BUYER_CODE}
AND A.COMPANY_CODE = B.BUYER AND A.TYPE = 'Z014' AND A.CODE = B.CODE2 AND B.TYPE = 'DTOA' AND B.CODE1 = NVL(#{st_dept_code},'') ) A ORDER BY ACCOUNT_NAME

